// --- פונקציה לייצור שאלות אוטומטיות מהמאגר של הנקודות (data) ---
// הפונקציה כעת מחזירה אובייקט שמחולק לקטגוריות כדי שנוכל לשלוף מהן למבחן המשוקלל
function generateAutoQuestions() {
    let autoQuestions = { location: [], element: [], special: [] };
    let allPoints = [];
    
    // רשימת הקידומות המותרות למבחן (ללא LIV, GB, TW, PC)
    const allowedPrefixes = ['LU', 'LI', 'ST', 'SP', 'HT', 'SI', 'BL', 'KID', 'CV', 'RN', 'REN', 'GV', 'DU'];
    
    for (let key in data) {
        if (data[key].points) {
            data[key].points.forEach(pt => {
                let isAllowed = allowedPrefixes.some(prefix => pt.id.startsWith(prefix) || pt.name.toUpperCase().startsWith(prefix));
                if (isAllowed) {
                    allPoints.push(pt);
                }
            });
        }
    }

    if(allPoints.length < 4) return autoQuestions;

    // 1. שאלות על מיקומים (location)
    let pointsWithLoc = allPoints.filter(p => p.loc && p.loc !== '');
    for(let i=0; i<15; i++) {
        if(pointsWithLoc.length < 4) break;
        let correctPt = pointsWithLoc[Math.floor(Math.random() * pointsWithLoc.length)];
        let correctAns = correctPt.loc;
        
        let wrongOptions = [];
        let shuffled = [...pointsWithLoc].sort(() => 0.5 - Math.random());
        for(let p of shuffled) {
            if(p.loc !== correctAns && !wrongOptions.includes(p.loc)) {
                wrongOptions.push(p.loc);
            }
            if(wrongOptions.length === 3) break;
        }
        
        let opts = [correctAns, ...wrongOptions];
        opts.sort(() => 0.5 - Math.random());
        
        autoQuestions.location.push({
            cat: "location",
            q: `מהו המיקום המדויק של הנקודה ${correctPt.id} (${correctPt.name})?`,
            options: opts,
            correct: opts.indexOf(correctAns)
        });
    }

    // 2. שאלות על אלמנטים (element)
    const fiveElements = ['עץ', 'אש', 'אדמה', 'מתכת', 'מים'];
    let pointsWithElm = allPoints.filter(p => p.elmN && p.elmN.includes('אלמנט'));
    for(let i=0; i<10; i++) {
        if(pointsWithElm.length < 1) break;
        let correctPt = pointsWithElm[Math.floor(Math.random() * pointsWithElm.length)];
        let correctAns = correctPt.elmN.replace('אלמנט: ', '').trim();
        
        let wrongElements = fiveElements.filter(e => e !== correctAns);
        wrongElements = wrongElements.sort(() => 0.5 - Math.random()).slice(0, 3);
        
        let opts = [correctAns, ...wrongElements];
        opts.sort(() => 0.5 - Math.random());
        
        autoQuestions.element.push({
            cat: "element",
            q: `לאיזה אלמנט (במסגרת חמשת האלמנטים) משויכת הנקודה ${correctPt.id}?`,
            options: opts,
            correct: opts.indexOf(correctAns)
        });
    }

    // 3. שאלות על קבוצות וקטגוריות - נכנס לתוך המפגש/פתיחה (special)
    let allTags = [];
    allPoints.forEach(p => {
        if(p.tags) {
            p.tags.forEach(t => {
                if(!allTags.includes(t)) allTags.push(t);
            });
        }
    });

    for(let i=0; i<10; i++) {
        if(allTags.length === 0) break;
        let tag = allTags[Math.floor(Math.random() * allTags.length)];
        let correctPts = allPoints.filter(p => p.tags && p.tags.includes(tag));
        let incorrectPts = allPoints.filter(p => !(p.tags && p.tags.includes(tag)));
        
        if(correctPts.length > 0 && incorrectPts.length >= 3) {
            let correctPt = correctPts[Math.floor(Math.random() * correctPts.length)];
            let wrongOptions = [...incorrectPts].sort(() => 0.5 - Math.random()).slice(0, 3).map(p => p.id);
            
            let opts = [...wrongOptions, correctPt.id];
            let correctAns = correctPt.id;
            opts.sort(() => 0.5 - Math.random());
            
            autoQuestions.special.push({
                cat: "special",
                q: `איזו מהנקודות הבאות מוגדרת כנקודת ${tag}?`,
                options: opts,
                correct: opts.indexOf(correctAns)
            });
        }
    }

    return autoQuestions;
}

// --- המערכת למבחן העיוני (הגרסה החדשה והמשוקללת) ---
let currentExamQuestions = [];
let currentExamIndex = 0;
let examScore = 0;
let isExamActive = false; 

function startTheoreticalExam() {
    let autoGenerated = generateAutoQuestions();
    
    // פונקציית ערבוב אמיתית (Fisher-Yates) שפותרת את בעיית החזרתיות של JavaScript
    function shuffle(array) {
        let currentIndex = array.length, randomIndex;
        while (currentIndex != 0) {
            randomIndex = Math.floor(Math.random() * currentIndex);
            currentIndex--;
            [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
        }
        return array;
    }
    
    // מערבבים את המאגר הידני יחד עם המאגר האוטומטי לפי קטגוריות בעזרת הערבוב החדש
    let allLocations = shuffle([...manualExamBank.filter(q => q.cat === 'location'), ...autoGenerated.location]);
    let allElements = shuffle([...manualExamBank.filter(q => q.cat === 'element'), ...autoGenerated.element]);
    let allCycles = shuffle(manualExamBank.filter(q => q.cat === 'cycle'));
    let allSpecials = shuffle([...manualExamBank.filter(q => q.cat === 'special'), ...autoGenerated.special]);
    let allCases = shuffle(manualExamBank.filter(q => q.cat === 'case'));
    let allMisc = shuffle(manualExamBank.filter(q => q.cat === 'misc'));

    // החיתוך לפי האחוזים המדויקים (מבחן של 20 שאלות)
    // 10% = 2 שאלות
    // 40% = 8 שאלות
    // 20% = 4 שאלות
    let finalExam = [
        ...allLocations.slice(0, 2),    // 10% מיקומים
        ...allElements.slice(0, 2),     // 10% אלמנטים
        ...allCycles.slice(0, 2),       // 10% מעגל הזנה/בקרה
        ...allSpecials.slice(0, 2),     // 10% נקודות מפגש/פתיחה מיוחדות
        ...allCases.slice(0, 8),        // 40% מקרי בוחן
        ...allMisc.slice(0, 4)          // 20% שונות
    ];
    
    // ערבוב סופי של המבחן לפני הצגתו כדי שהנושאים לא יופיעו תמיד באותו סדר
    currentExamQuestions = shuffle(finalExam);
    currentExamIndex = 0;
    examScore = 0;
    isExamActive = true;
    
    document.getElementById('exam-start-screen').style.display = 'none';
    renderExamQuestion();
}


function resumeExamIfActive() {
    if (isExamActive && currentExamQuestions.length > 0) {
        document.getElementById('exam-start-screen').style.display = 'none';
        renderExamQuestion();
    }
}

function endTheoreticalExam() {
    isExamActive = false;
    currentExamQuestions = [];
    currentExamIndex = 0;
    examScore = 0;
    
    document.getElementById('exam-container').style.display = 'none';
    document.getElementById('exam-start-screen').style.display = 'block';
}

function renderExamQuestion() {
    const container = document.getElementById('exam-container');
    if (!container) return;
    
    container.style.display = 'block';

    if (currentExamIndex >= currentExamQuestions.length) {
        isExamActive = false;
        let pass = examScore >= 12; 
        container.innerHTML = `
            <div style="background: white; padding: 50px 30px; border-radius: 20px; box-shadow: 0 10px 30px rgba(0,0,0,0.08); width: 100%; box-sizing: border-box; margin: auto; text-align: center;">
                <h2 style="color: var(--ink); margin-bottom: 20px; font-size: 2.2rem;">סיום המבחן העיוני!</h2>
                <div style="font-size: 5rem; margin-bottom: 15px;">${pass ? '🏆' : '📚'}</div>
                <h3 style="color: ${pass ? '#2ecc71' : '#ff6b6b'}; font-size: 2.5rem; margin-bottom: 10px;">הציון שלך: ${(examScore / currentExamQuestions.length) * 100}%</h3>
                <p style="font-size: 1.3rem; color: #666; margin-bottom: 40px;">ענית נכון על <strong>${examScore}</strong> מתוך <strong>${currentExamQuestions.length}</strong> שאלות.</p>
                <div style="display: flex; justify-content: center; gap: 15px; flex-wrap: wrap;">
                    <button onclick="endTheoreticalExam()" style="background: #f0f2f5; color: var(--ink); border: none; padding: 15px 30px; font-size: 1.1rem; border-radius: 30px; cursor: pointer; font-weight: bold; transition: 0.2s;" onmouseover="this.style.background='#e4e6e9'" onmouseout="this.style.background='#f0f2f5'">חזור להתחלה</button>
                    <button onclick="startTheoreticalExam()" style="background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); color: white; border: none; padding: 15px 35px; font-size: 1.1rem; border-radius: 30px; cursor: pointer; font-weight: bold; box-shadow: 0 4px 15px rgba(161, 140, 209, 0.4); transition: 0.2s;" onmouseover="this.style.transform='translateY(-2px)'" onmouseout="this.style.transform='translateY(0)'">🔄 נסה שוב</button>
                </div>
            </div>
        `;
        return;
    }

    const qData = currentExamQuestions[currentExamIndex];
    let progressPercent = (currentExamIndex / currentExamQuestions.length) * 100;
    
    let html = `
        <style>
            .exam-opt-btn {
                background: #fdfbf7; 
                border: 2px solid #eaeaea; 
                padding: 18px 25px; 
                font-size: 1.15rem; 
                border-radius: 12px; 
                cursor: pointer; 
                transition: all 0.2s ease; 
                text-align: right; 
                color: var(--ink); 
                position: relative;
                font-family: inherit;
                outline: none;
                width: 100%;
            }
            .exam-opt-btn:hover:not([disabled]) {
                background: #fff;
                border-color: #a18cd1;
                transform: translateY(-2px);
                box-shadow: 0 5px 15px rgba(161, 140, 209, 0.15);
            }
            .exam-next-btn {
                background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%);
                color: white; 
                border: none; 
                padding: 12px 30px; 
                font-size: 1.2rem; 
                border-radius: 30px; 
                cursor: pointer; 
                font-weight: bold;
                box-shadow: 0 4px 15px rgba(161, 140, 209, 0.4);
                transition: transform 0.2s ease, box-shadow 0.2s ease;
                display: inline-flex;
                align-items: center;
                gap: 10px;
                font-family: inherit;
                outline: none;
            }
            .exam-next-btn:hover {
                transform: translateY(-2px);
                box-shadow: 0 6px 20px rgba(161, 140, 209, 0.6);
            }
        </style>
        <div style="background: white; padding: 40px; border-radius: 20px; box-shadow: 0 10px 30px rgba(0,0,0,0.08); width: 100%; box-sizing: border-box; margin: auto; position: relative;">
            
            <!-- כפתור יציאה מהמבחן -->
            <button onclick="endTheoreticalExam()" style="position: absolute; top: 15px; left: 15px; background: none; border: none; color: #ff6b6b; font-size: 0.9rem; cursor: pointer; text-decoration: underline; font-weight: bold;">סיום המבחן ויציאה</button>

            <!-- סרגל התקדמות -->
            <div style="width: 100%; background: #f0f2f5; border-radius: 10px; height: 8px; margin-bottom: 25px; margin-top: 15px; overflow: hidden;">
                <div style="width: ${progressPercent}%; background: linear-gradient(90deg, #84fab0, #8fd3f4); height: 100%; transition: width 0.4s ease; border-radius: 10px;"></div>
            </div>

            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 25px; color: #666; font-size: 1rem; font-weight: bold;">
                <span style="background: #f8f9fa; padding: 6px 16px; border-radius: 20px; border: 1px solid #eee;">שאלה ${currentExamIndex + 1} מתוך ${currentExamQuestions.length}</span>
                <span style="background: #fff8e1; padding: 6px 16px; border-radius: 20px; border: 1px solid #ffecb3; color: #b78103;">ציון ביניים: ${examScore}</span>
            </div>
            
            <h3 style="color: var(--ink); font-size: 1.5rem; margin-bottom: 35px; line-height: 1.5; border-right: 5px solid #a18cd1; padding-right: 20px;">${qData.q}</h3>
            
            <div style="display: flex; flex-direction: column; gap: 15px;">
    `;

    qData.options.forEach((opt, index) => {
        html += `<button class="exam-opt-btn" onclick="checkExamAnswer(${index}, ${qData.correct}, this)">${opt}</button>`;
    });

    html += `
            </div>
            <div id="exam-next-container" style="display: none; text-align: left; margin-top: 35px;">
                <button class="exam-next-btn" onclick="nextExamQuestion()">לשאלה הבאה <span style="font-size: 1.4rem; line-height: 1;">&larr;</span></button>
            </div>
        </div>
    `;
    container.innerHTML = html;
}

function checkExamAnswer(selectedIndex, correctIndex, btnElement) {
    const btns = document.querySelectorAll('.exam-opt-btn');
    btns.forEach(b => {
        b.disabled = true;
        b.style.cursor = 'not-allowed';
        b.style.opacity = '0.7';
    });

    if (selectedIndex === correctIndex) {
        btnElement.style.background = '#e8f5e9';
        btnElement.style.borderColor = '#28a745';
        btnElement.style.color = '#155724';
        btnElement.style.opacity = '1';
        btnElement.style.boxShadow = '0 4px 15px rgba(40, 167, 69, 0.2)';
        examScore++;
    } else {
        btnElement.style.background = '#fdeded';
        btnElement.style.borderColor = '#dc3545';
        btnElement.style.color = '#721c24';
        btnElement.style.opacity = '1';
        
        btns[correctIndex].style.background = '#e8f5e9';
        btns[correctIndex].style.borderColor = '#28a745';
        btns[correctIndex].style.color = '#155724';
        btns[correctIndex].style.opacity = '1';
    }

    document.getElementById('exam-next-container').style.display = 'block';
}

function nextExamQuestion() {
    currentExamIndex++;
    renderExamQuestion();
}